import { DEFAULT_PARAMS, paramCatalog } from './params';

/** Renders the parameter catalogue as Markdown (docs/game-parameters.md). */
export function renderParamsDoc(): string {
  const rows = paramCatalog(DEFAULT_PARAMS);
  const esc = (s: string) => s.replace(/\|/g, '\\|');
  const lines = [
    '<!-- GENERATED by `pnpm params:doc` from packages/shared/src/params.ts — do not edit by hand. -->',
    '',
    '# Game parameters',
    '',
    'Every tunable value in the game, with its status:',
    '',
    '- **approved** — a rule fixed by the design specification.',
    '- **provisional** — a placeholder so the game can run. It is *not* an official',
    '  rule and must be confirmed by simulations or a design decision.',
    '',
    'All values can be overridden without a code change with a JSON file passed in',
    '`TIO_PARAMS_FILE` (unknown keys and type changes are rejected). The live values',
    'are served at `GET /api/params` and shown in the app under *More → Game rules*.',
    '',
    `Approved: ${rows.filter((r) => r.status === 'approved').length} · Provisional: ${rows.filter((r) => r.status === 'provisional').length}`,
    '',
  ];
  let group = '';
  for (const r of rows) {
    const g = r.path.split('.')[0]!;
    if (g !== group) {
      group = g;
      lines.push(`## ${g}`, '', '| Parameter | Value | Status | Notes |', '|---|---|---|---|');
    }
    lines.push(`| \`${r.path}\` | ${String(r.value)} | ${r.status} | ${esc(r.note ?? '')} |`);
    const next = rows[rows.indexOf(r) + 1];
    if (!next || next.path.split('.')[0] !== g) lines.push('');
  }
  return lines.join('\n');
}
